"use client";

import type { DetailsHTMLAttributes, HTMLAttributes } from "react";

export function Collapsible({ open, onOpenChange, className = "", ...props }: Omit<DetailsHTMLAttributes<HTMLDetailsElement>, "onToggle"> & { open?: boolean; onOpenChange?: (open: boolean) => void }) { return <details open={open} className={`co-group co-rounded-lg co-border co-border-black/15 ${className}`.trim()} onToggle={(event) => onOpenChange?.(event.currentTarget.open)} {...props} />; }
export function CollapsibleTrigger({ className = "", children, ...props }: HTMLAttributes<HTMLElement>) { return <summary className={`co-flex co-cursor-pointer co-list-none co-items-center co-justify-between co-p-4 co-font-medium focus-visible:co-ring-2 ${className}`.trim()} {...props}>{children}<span aria-hidden="true" className="co-ms-2 co-inline-block co-transition group-open:co-rotate-180">↓</span></summary>; }
export function CollapsibleContent({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-border-t co-border-black/15 co-p-4 co-text-sm ${className}`.trim()} {...props} />; }
